  // ---- drawing helpers for country-specific scenes ----
  function E(x, y, rx, ry, c) { return '<ellipse cx="' + x + '" cy="' + y + '" rx="' + rx + '" ry="' + ry + '" fill="' + c + '"/>'; }
  function T(x, b, w, h, c) { return P('M' + (x - w / 2) + ' ' + b + ' L' + x + ' ' + (b - h) + ' L' + (x + w / 2) + ' ' + b + ' Z', c); }
  function SKY(c) { return R(0, 0, 200, 200, c); }
  function GND(y, c) { return R(0, y, 200, 210 - y, c); }
  function HILL(y, a, c) { return P('M0 ' + y + ' Q50 ' + (y - a) + ' 100 ' + y + ' Q150 ' + (y + a) + ' 200 ' + y + ' L200 200 L0 200 Z', c); }
  function PALM(x, y, s) { s = s || 1; var tx = x + 10 * s, ty = y - 32 * s; return L('M' + x + ' ' + y + ' Q' + (x + 4 * s) + ' ' + (y - 18 * s) + ' ' + tx + ' ' + ty, '#7F5539', 3.5 * s) + L('M' + tx + ' ' + ty + ' Q' + (tx - 12 * s) + ' ' + (ty - 6 * s) + ' ' + (tx - 20 * s) + ' ' + (ty + 5 * s) + ' M' + tx + ' ' + ty + ' Q' + (tx + 12 * s) + ' ' + (ty - 8 * s) + ' ' + (tx + 20 * s) + ' ' + (ty + 3 * s) + ' M' + tx + ' ' + ty + ' Q' + (tx - 4 * s) + ' ' + (ty - 14 * s) + ' ' + (tx - 14 * s) + ' ' + (ty - 14 * s) + ' M' + tx + ' ' + ty + ' Q' + (tx + 6 * s) + ' ' + (ty - 14 * s) + ' ' + (tx + 16 * s) + ' ' + (ty - 13 * s), '#2B9348', 3.5 * s); }
  function PINE(x, y, h, c) { return T(x, y, h * 0.6, h, c || '#1B4332'); }
  function TREE(x, y, r, c) { return R(x - 1.5, y - r, 3, r, '#6B4E3D') + C(x, y - r, r, c || '#40916C'); }
  function BIRD(x, y, s, c) { return L('M' + (x - 6 * s) + ' ' + y + ' Q' + (x - 3 * s) + ' ' + (y - 4 * s) + ' ' + x + ' ' + y + ' Q' + (x + 3 * s) + ' ' + (y - 4 * s) + ' ' + (x + 6 * s) + ' ' + y, c || '#14261B', 1.6); }
  function SAILBOAT(x, y, s, c) { return P('M' + (x - 12 * s) + ' ' + y + ' L' + (x + 12 * s) + ' ' + y + ' L' + (x + 8 * s) + ' ' + (y + 5 * s) + ' L' + (x - 8 * s) + ' ' + (y + 5 * s) + ' Z', '#5A3A22') + P('M' + x + ' ' + (y - 1) + ' L' + x + ' ' + (y - 22 * s) + ' L' + (x + 11 * s) + ' ' + (y - 1) + ' Z', c || '#FFFFFF') + L('M' + x + ' ' + y + ' L' + x + ' ' + (y - 24 * s), '#5A3A22', 1.2); }
  function LEGS(xs, y, len, c, w) { var d = ''; xs.forEach(function (x) { d += 'M' + x + ' ' + y + ' L' + x + ' ' + (y + len) + ' '; }); return L(d, c, w); }
  function ELEPHANT(x, y, s, c) { c = c || '#6B6B6B'; return E(x, y, 14 * s, 9 * s, c) + C(x + 15 * s, y - 4 * s, 6.5 * s, c) + L('M' + (x + 19 * s) + ' ' + (y - 2 * s) + ' Q' + (x + 23 * s) + ' ' + (y + 6 * s) + ' ' + (x + 20 * s) + ' ' + (y + 12 * s), c, 3 * s) + R(x - 10 * s, y + 4 * s, 4 * s, 9 * s, c) + R(x + 5 * s, y + 4 * s, 4 * s, 9 * s, c) + E(x + 12 * s, y - 5 * s, 3.5 * s, 5 * s, '#5A5A5A'); }
  function GIRAFFE(x, y, s) { var c = '#E9A43B'; return E(x, y, 11 * s, 6 * s, c) + L('M' + (x + 8 * s) + ' ' + (y - 3 * s) + ' L' + (x + 14 * s) + ' ' + (y - 26 * s), c, 4 * s) + E(x + 16 * s, y - 27 * s, 4.5 * s, 2.6 * s, c) + LEGS([x - 7 * s, x - 3 * s, x + 4 * s, x + 8 * s], y + 4 * s, 13 * s, c, 2.2 * s) + C(x - 3 * s, y - 1 * s, 1.6 * s, '#8D5524') + C(x + 4 * s, y + 1 * s, 1.6 * s, '#8D5524'); }
  function CAMEL(x, y, s, c, twoHumps) { c = c || '#C08A4B'; return E(x, y, 12 * s, 6 * s, c) + C(x - (twoHumps ? 4 : 0) * s, y - 6 * s, 5 * s, c) + (twoHumps ? C(x + 5 * s, y - 6 * s, 5 * s, c) : '') + L('M' + (x + 10 * s) + ' ' + (y - 2 * s) + ' Q' + (x + 16 * s) + ' ' + (y - 6 * s) + ' ' + (x + 16 * s) + ' ' + (y - 14 * s), c, 3 * s) + E(x + 18 * s, y - 15 * s, 4 * s, 2.5 * s, c) + LEGS([x - 8 * s, x - 4 * s, x + 5 * s, x + 9 * s], y + 4 * s, 12 * s, c, 2.2 * s); }
  function LLAMA(x, y, s, c) { c = c || '#F1E3C4'; return E(x, y, 10 * s, 6 * s, c) + L('M' + (x + 7 * s) + ' ' + (y - 2 * s) + ' L' + (x + 9 * s) + ' ' + (y - 18 * s), c, 4 * s) + E(x + 11 * s, y - 19 * s, 4 * s, 2.6 * s, c) + L('M' + (x + 8 * s) + ' ' + (y - 21 * s) + ' L' + (x + 8 * s) + ' ' + (y - 25 * s), c, 1.5 * s) + LEGS([x - 6 * s, x - 2 * s, x + 3 * s, x + 7 * s], y + 4 * s, 10 * s, c, 2.2 * s); }
